/// Looks up the authored list for a name.
pub fn properties(name: &str) -> Option<&'static [&'static str]> {
    PROPERTIES
        .binary_search_by(|(key, _)| (*key).cmp(name))
        .ok()
        .and_then(|index| PROPERTIES.get(index))
        .map(|(_, values)| *values)
}
